from zipfile import ZipFile
from lxml import etree
fn='documents/turn-2-redline-meridian.docx'
with ZipFile(fn) as z: root=etree.fromstring(z.read('word/document.xml'))
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
body=root.xpath('.//w:body',namespaces=ns)[0]
for i,p in enumerate(body.xpath('./w:p',namespaces=ns)):
    parts=[]
    for child in p:
      tag=etree.QName(child).localname
      if tag=='ins': parts.append('[INS '+''.join(child.xpath('.//w:t/text()',namespaces=ns))+']')
      elif tag=='del': parts.append('[DEL '+''.join(child.xpath('.//w:delText/text()',namespaces=ns))+']')
      elif tag=='r': parts.append(''.join(child.xpath('.//w:t/text()',namespaces=ns)))
      elif tag=='hyperlink': parts.append(''.join(child.xpath('.//w:t/text()',namespaces=ns)))
    s=''.join(parts)
    if '[INS' in s or '[DEL' in s:
      print(f'{i}: {s[:1000]}')
PY","description":"List Turn 2 tracked changes"}

