from zipfile import ZipFile
from lxml import etree
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
def get(fn):
 with ZipFile(fn) as z: root=etree.fromstring(z.read('word/document.xml'))
 arr=[]
 for p in root.xpath('.//w:body/w:p',namespaces=ns):
  # visible/track text
  s=''
  for n in p.iter():
   t=etree.QName(n).localname
   if t in ['t','delText']: s+=n.text or ''
  arr.append(s)
 return arr
for i,(a,b) in enumerate(zip(get('documents/turn-1-draft-gmra-voss.docx'),get('documents/turn-2-redline-meridian.docx'))):
 if a!=b:
  print('IDX',i,'\nT1',a[:500],'\nT2',b[:500],'\n')
PY","description":"Compare Turn 1 and Turn 2 paragraph text"}

