from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from copy import deepcopy
from pathlib import Path
import shutil, os, re, datetime

SRC=Path('documents/turn-2-redline-meridian.docx')
OUT=Path('output/turn-3-redline-gmra.docx')
TMP=Path('/tmp/turn3doc')
if TMP.exists(): shutil.rmtree(TMP)
TMP.mkdir(parents=True)
with ZipFile(SRC) as z: z.extractall(TMP)

W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
R='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
CT='http://schemas.openxmlformats.org/package/2006/content-types'
ns={'w':W,'r':R}
qn=lambda n: '{%s}%s'%(W,n)

xmlp=TMP/'word/document.xml'
tree=etree.parse(str(xmlp)); root=tree.getroot()
body=root.find('.//'+qn('body'))

# Accept the Turn 2 changes to create the effective Turn 2 text as the Turn 3 comparison base.
def accept_changes(parent):
    for child in list(parent):
        tag=etree.QName(child).localname
        if tag=='ins':
            idx=parent.index(child)
            kids=list(child)
            for k in kids:
                parent.insert(idx, k); idx += 1
            parent.remove(child)
        elif tag=='del':
            parent.remove(child)
        else:
            accept_changes(child)
accept_changes(root)

# Helpers
def text_of(p):
    return ''.join(p.xpath('.//w:t/text()', namespaces=ns))
def first_rpr(p):
    r=p.find('.//'+qn('r'))
    if r is not None:
        rp=r.find(qn('rPr'))
        return deepcopy(rp) if rp is not None else None
    return None
def run(text, rpr=None, deltext=False):
    r=etree.Element(qn('r'))
    if rpr is not None: r.append(deepcopy(rpr))
    t=etree.SubElement(r, qn('delText' if deltext else 't'))
    if text.startswith(' ') or text.endswith(' ') or '  ' in text:
        t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    t.text=text
    return r
def simple_replace(p, newtext):
    rpr=first_rpr(p)
    for c in list(p):
        if etree.QName(c).localname!='pPr': p.remove(c)
    p.append(run(newtext,rpr))
def meta(author='Pryor, Ashworth & Gelb LLP'):
    return {'{'+W+'}author':author,'{'+W+'}date':'2025-04-15T13:00:00Z','{'+W+'}id':str(next_id())}
_next=100
def next_id():
    global _next
    v=_next; _next+=1; return v

def ins_el(text, rpr=None, cid=None, author='Pryor, Ashworth & Gelb LLP'):
    e=etree.Element(qn('ins'), meta(author))
    e.append(run(text,rpr))
    if cid is not None: # comment reference within insertion
        pass
    return e
def del_el(text, rpr=None, author='Pryor, Ashworth & Gelb LLP'):
    e=etree.Element(qn('del'), meta(author))
    e.append(run(text,rpr,True))
    return e

def tracked_replace(p, oldtext, newtext, comment_id=None, comment_after=True):
    rpr=first_rpr(p)
    for c in list(p):
        if etree.QName(c).localname!='pPr': p.remove(c)
    if comment_id is not None:
        p.append(etree.Element(qn('commentRangeStart'), {qn('id'):str(comment_id)}))
    p.append(del_el(oldtext,rpr))
    p.append(ins_el(newtext,rpr))
    if comment_id is not None:
        p.append(etree.Element(qn('commentRangeEnd'), {qn('id'):str(comment_id)}))
