from pathlib import Path
src='output/turn-3-redline-gmra.docx'; out='/tmp/no-comments.docx'
with ZipFile(src) as z:
  with ZipFile(out,'w',ZIP_DEFLATED) as o:
    for i in z.infolist():
      if i.filename in ['word/comments.xml']: continue
      if i.filename=='word/_rels/document.xml.rels':
        from lxml import etree
        r=etree.fromstring(z.read(i.filename)); ns={'pr':'http://schemas.openxmlformats.org/package/2006/relationships'}
        for el in list(r):
          if el.get('Type','').endswith('/comments'): r.remove(el)
        data=etree.tostring(r,xml_declaration=True,encoding='UTF-8',standalone='yes')
      elif i.filename=='[Content_Types].xml':
        from lxml import etree
        r=etree.fromstring(z.read(i.filename));
        for el in list(r):
          if el.get('PartName')=='/word/comments.xml': r.remove(el)
        data=etree.tostring(r,xml_declaration=True,encoding='UTF-8',standalone='yes')
      else: data=z.read(i.filename)
      o.writestr(i,data)
print(out)
