from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
src='output/turn-3-redline-gmra.docx'; out='/tmp/no-track.docx'; W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'; ns={'w':W}
with ZipFile(src) as z:
  root=etree.fromstring(z.read('word/document.xml'))
  def acc(parent):
   for c in list(parent):
    t=etree.QName(c).localname
    if t=='ins':
     i=parent.index(c)
     for k in list(c): parent.insert(i,k); i+=1
     parent.remove(c)
    elif t=='del': parent.remove(c)
    else: acc(c)
  acc(root)
  data=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone='yes')
  with ZipFile(out,'w',ZIP_DEFLATED) as o:
   for i in z.infolist():
    if i.filename=='word/document.xml': o.writestr(i,data)
    elif i.filename=='word/comments.xml': continue
    elif i.filename=='word/_rels/document.xml.rels':
     r=etree.fromstring(z.read(i.filename));
     for el in list(r):
      if el.get('Type','').endswith('/comments'): r.remove(el)
     o.writestr(i,etree.tostring(r,xml_declaration=True,encoding='UTF-8',standalone='yes'))
    elif i.filename=='[Content_Types].xml':
     r=etree.fromstring(z.read(i.filename));
     for el in list(r):
      if el.get('PartName')=='/word/comments.xml': r.remove(el)
     o.writestr(i,etree.tostring(r,xml_declaration=True,encoding='UTF-8',standalone='yes'))
    else: o.writestr(i,z.read(i.filename))
PY
